const item = $input.first().json || {};
const body = item.body ? item.body : item;
const message = (body.message || '').toString().trim();
return [{ json: {
  student_id: body.student_id || 'anonymous',
  message: message,
  topic: body.topic || null,
  has_message: message.length > 0
} }];

const src = $("02 - Parse Message").first().json;
const understand = ($("03 - Understand Agent").first().json || {}).output || {};
const supervisor = ($("04 - Supervisor Agent").first().json || {}).output || {};
const action = (supervisor.action || 'TEACH').toUpperCase();
const topic = supervisor.topic || (understand.topics && understand.topics[0]) || src.topic || 'Percentages';
let response = supervisor.response || understand.goal || ('Next action: ' + action + ' on ' + topic);
if (typeof response !== 'string') response = JSON.stringify(response);
return [{ json: {
  ok: true,
  action,
  topic,
  response,
  state: { mastery: null },
  student_state: {
    student_id: src.student_id,
    goal: understand.goal || null,
    days_remaining: (understand.constraints || {}).days_remaining || null,
    daily_study_minutes: (understand.constraints || {}).daily_hours ? Number(understand.constraints.daily_hours) * 60 : null
  }
} }];
